import{_ as r}from"./chunks/projects-sidebar-colors.DIY830dX.js";import{_ as s,a as t,b as a}from"./chunks/weiteres-beispiel.Chd7zmRi.js";import{_ as i,o as n,c as o,a3 as l}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"Couleurs du menu latéral","description":"Couleurs et opacité par entrée du menu HA, directement dans l’éditeur natif. HACS et Marketplace, DE/EN/FR.","frontmatter":{"title":"Couleurs du menu latéral","description":"Couleurs et opacité par entrée du menu HA, directement dans l’éditeur natif. HACS et Marketplace, DE/EN/FR."},"headers":[],"relativePath":"fr/projects/sidebar-colors/index.md","filePath":"fr/projects/sidebar-colors/index.md","lastUpdated":1794509069000}'),u={name:"fr/projects/sidebar-colors/index.md"};function c(d,e,p,m,g,h){return n(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="couleurs-du-menu-lateral-sidebar-colors" tabindex="-1">Couleurs du menu latéral / Sidebar Colors <a class="header-anchor" href="#couleurs-du-menu-lateral-sidebar-colors" aria-label="Permalink to &quot;Couleurs du menu latéral / Sidebar Colors&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">HA 2026.11 : sélecteur corrigé</p><p>La version <strong>0.1.1</strong> prend en charge <code>ha-md-list-item</code> et <code>ha-list-item-button</code> dans le dialogue natif. Les 27 tests locaux réussissent : régressions DOM des deux types de lignes HA, opacité, annulation, enregistrement, réouverture et réinitialisation au thème. Le correctif correspondant du Manager a été testé sur .177 ; Sidebar Colors n’a pas été installé en parallèle. Couleurs et clés de stockage existantes conservées.</p></div><p><a href="/fr/collection/ha-2026-11-compatibility">Périmètre, résultats et problèmes ouverts</a>.</p><img src="'+r+'" width="80" height="80" alt="Sidebar Colors"><p><strong>0.1.1 · Extension frontend · DE / EN / FR · MIT</strong></p><p>Attribuer une couleur propre à l’icône et au libellé de chaque entrée Home Assistant. Le nouveau carré de couleur se trouve directement dans <strong>Modifier la barre latérale</strong>, entre le nom et l’œil. La visibilité et l’ordre restent réglables avec les commandes natives habituelles.</p><p><a href="https://github.com/rockbaer2007/ha-sidebar-colors" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://github.com/rockbaer2007/ha-sidebar-colors/releases/latest" target="_blank" rel="noreferrer">Téléchargement / Versions</a> · <a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=ha-sidebar-colors&amp;category=plugin" target="_blank" rel="noreferrer">Ouvrir dans HACS</a></p><h2 id="selecteur-de-couleur" tabindex="-1">Sélecteur de couleur <a class="header-anchor" href="#selecteur-de-couleur" aria-label="Permalink to &quot;Sélecteur de couleur&quot;">​</a></h2><p>Zone de saturation/luminosité, curseur de teinte, saisie HEX et opacité avec aperçu immédiat. Le damier représente la transparence. <strong>Appliquer</strong> ferme le sélecteur ; seul <strong>Enregistrer</strong> dans la fenêtre HA sauvegarde durablement. <strong>Annuler</strong> abandonne le brouillon correspondant. <strong>Couleur du thème</strong> supprime la couleur personnalisée de l’entrée.</p><p><img src="'+s+'" alt="Sélecteur ATLAS avec une opacité de 70 pour cent"></p><h2 id="exemples-de-l-utilisateur" tabindex="-1">Exemples de l’utilisateur <a class="header-anchor" href="#exemples-de-l-utilisateur" aria-label="Permalink to &quot;Exemples de l’utilisateur&quot;">​</a></h2><p>Les images montrent des couleurs choisies individuellement pour les icônes et les textes. Des noms identiques restent distincts grâce aux chemins des panneaux. Aucune palette n’est imposée.</p><div class="sidebar-color-examples"><figure><a href="/images/sidebar-colors/beispiel.png" target="_blank" rel="noopener noreferrer"><img src="'+t+'" alt="Menu coloré avec Vue d’ensemble, ATLAS et HACS"></a><figcaption>Premier résultat avec des couleurs personnalisées.</figcaption></figure><figure><a href="/images/sidebar-colors/weiteres-beispiel.png" target="_blank" rel="noopener noreferrer"><img src="'+a+`" alt="Autre exemple avec les outils ATLAS et Zigbee2MQTT"></a><figcaption>Autre configuration avec les outils ATLAS.</figcaption></figure></div><h2 id="prerequis-et-verifications" tabindex="-1">Prérequis et vérifications <a class="header-anchor" href="#prerequis-et-verifications" aria-label="Permalink to &quot;Prérequis et vérifications&quot;">​</a></h2><p>Version minimale prévue : <strong>Home Assistant Core 2026.10.3</strong>. Tests réels sous <strong>2026.10.4</strong> : choix des couleurs, opacité de 70 % et de 0 %, aperçu, enregistrement/annulation, rechargement, retour au thème, synchronisation entre deux onglets et commandes natives de visibilité/tri. L’utilisateur confirme le résultat. La couleur temporaire du test a été supprimée ; ses couleurs personnelles ont été conservées.</p><p>La version minimale repose sur les interfaces disponibles, sans test réel distinct sous 2026.10.3. Marketplace à partir de <strong>2026.11</strong> utilise le même format compatible HACS ; aucun test d’exécution séparé n’y est revendiqué. <a href="https://contributors.home-assistant.io/marketplace/how-it-works/" target="_blank" rel="noreferrer">Description officielle de Marketplace</a></p><h2 id="installation-hacs-marketplace" tabindex="-1">Installation HACS / Marketplace <a class="header-anchor" href="#installation-hacs-marketplace" aria-label="Permalink to &quot;Installation HACS / Marketplace&quot;">​</a></h2><p>Créer d’abord une sauvegarde complète de HA. C’est un <strong>plugin frontend</strong>, pas une application Supervisor ni une carte à insérer. Il est d’abord disponible comme dépôt personnalisé ; sa publication ne l’ajoute pas automatiquement au catalogue par défaut.</p><ol><li>Dans HACS, ajouter <code>https://github.com/rockbaer2007/ha-sidebar-colors</code> via <strong>Dépôts personnalisés</strong>, catégorie <strong>Tableau de bord</strong> (<code>plugin</code>), puis télécharger <strong>Sidebar Colors</strong>.</li><li>À partir de 2026.11, utiliser la procédure correspondante sous <strong>Paramètres → Marketplace</strong>. Marketplace reprend les réglages HACS ; aucun format de migration séparé n’est requis.</li><li>Compléter la section <code>frontend:</code> existante. Garder les thèmes et modules présents ; ne pas créer une section en double :</li></ol><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  extra_module_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/hacsfiles/ha-sidebar-colors/ha-sidebar-colors.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ol start="4"><li>Vérifier la configuration, redémarrer HA puis recharger le navigateur. Une ressource de tableau de bord seule ne suffit pas si une autre page HA est ouverte d’abord. L’entrée de module charge aussi l’extension sur ces pages.</li><li>Maintenir l’en-tête <strong>Home Assistant</strong> du menu latéral puis cliquer sur un carré de couleur.</li></ol><h2 id="installation-manuelle-ou-migration" tabindex="-1">Installation manuelle ou migration <a class="header-anchor" href="#installation-manuelle-ou-migration" aria-label="Permalink to &quot;Installation manuelle ou migration&quot;">​</a></h2><p>Copier le fichier unique <code>ha-sidebar-colors.js</code> de la version publiée dans <code>/config/www/ha-sidebar-colors.js</code> et utiliser <code>/local/ha-sidebar-colors.js</code> comme module. Le ZIP contient le même fichier, la licence et la documentation. Ne pas charger les deux méthodes simultanément.</p><p>Pour l’ancien prototype à trois fichiers, remplacer <code>/local/ugso-sidebar-colors/0.1.0/sidebar-colors.js</code> par le nouveau chemin, redémarrer HA puis recharger le navigateur. Le stockage des couleurs reste identique ; les anciens fichiers peuvent rester comme sauvegarde.</p><h2 id="conserver-les-reglages-et-mettre-a-jour" tabindex="-1">Conserver les réglages et mettre à jour <a class="header-anchor" href="#conserver-les-reglages-et-mettre-a-jour" aria-label="Permalink to &quot;Conserver les réglages et mettre à jour&quot;">​</a></h2><p>Les couleurs sont enregistrées par utilisateur HA sous la clé séparée <code>ugso_sidebar_colors_v1</code> et synchronisées sur les appareils où l’extension est chargée. Les chemins des panneaux évitent les confusions de noms. Un enregistrement de couleurs seul ne réécrit ni l’ordre natif, ni les éléments masqués, ni le thème. Configurations des tableaux de bord et autorisations restent inchangées.</p><p>Avant l’enregistrement, l’ancien état des couleurs et des préférences est conservé localement dans <code>ugso-sidebar-colors-backup:&lt;user-id&gt;</code>. Cela ne remplace pas une sauvegarde HA complète. Un stockage navigateur plein ou bloqué empêche l’enregistrement. Aucun nouvel identifiant, script externe ou service de traduction cloud n’est nécessaire.</p><p>Mettre à jour via le même dépôt HACS/Marketplace, garder le chemin du module puis recharger le navigateur. Pour désinstaller, retirer uniquement l’entrée du module, redémarrer HA et recharger. Les couleurs du thème reviennent et les réglages natifs sont conservés.</p><h2 id="limites" tabindex="-1">Limites <a class="header-anchor" href="#limites" aria-label="Permalink to &quot;Limites&quot;">​</a></h2><p>L’extension utilise des méthodes internes des fenêtres HA ; la revérifier après les mises à jour du frontend. Les conflits et confirmations incertaines gardent le brouillon ouvert ; aucune répétition aveugle. Cette API n’offre pas de comparaison/enregistrement atomique. Couleurs et ordre natif sont deux opérations distinctes, avec compensation contrôlée au mieux en cas d’échec.</p><p>À 0 % d’opacité, icône et texte peuvent être invisibles, mais le carré reste accessible. Fond de sélection, titres et droits restent inchangés. Les pannes et conflits ont été simulés localement ; aucun test réel sur téléphone/tablette ni coupure réseau provoquée sous Marketplace n’est revendiqué. <a href="https://github.com/rockbaer2007/ha-sidebar-colors/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Détails des tests et code source</a>.</p>`,31)])])}const A=i(u,[["render",c]]);export{k as __pageData,A as default};
